const wchar_t* ps4rt_localize(const std::wstring& language, const wchar_t* english) {
    if (language == L"English" || language == L"Français") return english;
    for (const auto& row : kUi) {
        if (std::wcscmp(row.en, english)) continue;
        if (language == L"Español") return row.es;
        if (language == L"Português") return row.pt;
        if (language == L"Português (Brasil)") return row.br;
        if (language == L"Italiano") return row.it;
        if (language == L"Deutsch") return row.de;
        if (language == L"Русский") return row.ru;
        if (language == L"简体中文") return row.zh;
        if (language == L"繁體中文") return row.zht;
        if (language == L"한국어") return row.ko;
        if (language == L"日本語") return row.ja;
        return english;
    }
    return english;
}
